// TH14 v1.00b st01.ecl.txt MainSub01 (798-811) -> two GirlB01 (196-221) + GirlB01_at (223-251)
// Source frame 0 = card frame 0; first enemy one OPENING_BUFFER later.
const TIME_LIMIT: int = 2124;
const OPENING_BUFFER: int = 120;

// TH14 synthetic appearance aliases, see transcribe/th14/bullet-types.md.
const TH14_RING_BALL: int = 448; // native type 6
const TH14_RICE: int = 480;      // native type 8

// GirlB01_at: emitters configured at t=60, emitter 1 fires once, emitter 0 fires A times / 40f.
async sub girl_attack() {
    wait(60);
    var rank: int = global(GVAR_RANK);

    // etNew(1); etAim(1,3) fixed ring; etSprite(1,8,4); etCountD/etSpeedD below.
    sh_reset(1);
    sh_sprite(1, TH14_RICE, 4);
    sh_ring(1, 1);
    sh_aim(1, 0);
    var base: angle = rand(65536) as angle; // etAngle(1,%RANDRAD,...): one draw per attack
    sh_angle(1, base, 3deg);                // etAngle(1,..., 0.05235988) = 3 deg layer step
    if rank == RANK_EASY {
        sh_count(1, 6, 1);   // etCountD(1, 6,16,24,32, 1,1,2,3)
        sh_speed(1, 1.2fx, 0fx); // etSpeedD(1, 1.2,1.2,2.2,3.2, 1.0,1.0,1.0,1.0)
    } else if rank == RANK_NORMAL {
        sh_count(1, 16, 1);
        sh_speed(1, 1.2fx, 0fx);
    } else if rank == RANK_HARD {
        sh_count(1, 24, 2);
        sh_speed(1, 2.2fx, -1.2fx);
    } else {
        sh_count(1, 32, 3);
        sh_speed(1, 3.2fx, -1.1fx);
    }
    sh_fire(1); // etOn(1)

    // etNew(0); etAim(0,0) aimed fan; etSprite(0,6,6).
    sh_reset(0);
    sh_sprite(0, TH14_RING_BALL, 6);
    sh_ring(0, 0);
    sh_aim(0, 1);
    sh_angle(0, 0deg, 5deg); // etAngle(0, 0.0f, 0.05235988f)
    if rank == RANK_EASY {
        sh_count(0, 1, 1);   // etCountD(0, 1,1,5,5, 1,3,5,8)
        sh_speed(0, 1.2fx, 0fx); // etSpeedD(0, 1.2,1.2,2.2,3.2, 1.0,1.0,1.0,1.0)
    } else if rank == RANK_NORMAL {
        sh_count(0, 1, 3);
        sh_speed(0, 1.2fx, -0.1fx);
    } else if rank == RANK_HARD {
        sh_count(0, 5, 5);
        sh_speed(0, 2.2fx, -0.3fx);
    } else {
        sh_count(0, 5, 8);
        sh_speed(0, 3.2fx, -0.3142857fx);
    }

    var shots: int = 3; // diffI($A, 1,3,3,3)
    if rank == RANK_EASY { shots = 1; }
    for i in 0..shots {
        sh_fire(0); // etOn(0) inside GirlB01_at_676..716 loop
        wait(40);
    }
}

// GirlB01: entry state per source lines 196-221.
// mirror=1 reproduces moveSetMirror(1) taken when %FINAL_X > 0; it reflects later
// moveVel angles across x (pi/2 stays pi/2, pi/8 becomes 7pi/8).
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx); // setHurtbox(32,32) -> r=16
    set_hitbox(12fx);  // setHitbox(24,24) -> r=12
    var drift: angle = 22.5deg; // 0.3926991 rad
    if mirror != 0 { drift = 157.5deg; }

    move_vel(0, 90deg, 2.3fx, EASE_LINEAR); // moveVel(1.5707964f, 2.3f)
    move_speed(80, 0fx, EASE_QUAD_IN);      // moveVelTime(80,1,-999999,0): keep angle
    spawn girl_attack();                    // @GirlB01_at() async
    wait(180);
    move_vel(80, drift, 1fx, EASE_QUAD_IN); // moveVelTime(80,1,0.3926991f,1.0f)
    wait(60);
    loop { wait(1000); }                    // GirlB01_504/GirlB01_524 wait(1000) loop
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // MainSub01: both %PLAYER_X2 arms contain the same two creations, 60 frames apart.
    _ = spawn_enemy(128fx, -24fx, 400, 0, 1000, 0, girl(1));
    wait(60);
    _ = spawn_enemy(-96fx, -24fx, 400, 0, 1000, 0, girl(0));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
